<div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_10-使用示例" tabindex="-1"><a class="header-anchor" href="#_10-使用示例"><span>10. 使用示例</span></a></h3>
<div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre v-pre><code class="language-csharp"><span class="line"><span class="token comment">// SimpleService/Program.cs</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">using</span> <span class="token namespace">Croupier<span class="token punctuation">.</span>Sdk</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">using</span> <span class="token namespace">Croupier<span class="token punctuation">.</span>Sdk<span class="token punctuation">.</span>Extensions</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">using</span> <span class="token namespace">Croupier<span class="token punctuation">.</span>Sdk<span class="token punctuation">.</span>Models</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 创建客户端</span></span>
<span class="line"><span class="token class-name"><span class="token keyword">var</span></span> config <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token constructor-invocation class-name">ClientConfig</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    AgentAddr <span class="token operator">=</span> <span class="token string">"127.0.0.1:19090"</span><span class="token punctuation">,</span></span>
<span class="line">    ServiceId <span class="token operator">=</span> <span class="token string">"game-service-1"</span><span class="token punctuation">,</span></span>
<span class="line">    GameId <span class="token operator">=</span> <span class="token string">"my-game"</span><span class="token punctuation">,</span></span>
<span class="line">    Env <span class="token operator">=</span> <span class="token string">"production"</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">using</span> <span class="token class-name"><span class="token keyword">var</span></span> client <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token constructor-invocation class-name">CroupierClient</span><span class="token punctuation">(</span>config<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 注册函数</span></span>
<span class="line">client<span class="token punctuation">.</span><span class="token function">RegisterFunction</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token constructor-invocation class-name">FunctionDescriptor</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    Id <span class="token operator">=</span> <span class="token string">"player.get"</span><span class="token punctuation">,</span></span>
<span class="line">    Version <span class="token operator">=</span> <span class="token string">"1.0.0"</span><span class="token punctuation">,</span></span>
<span class="line">    Category <span class="token operator">=</span> <span class="token string">"player"</span><span class="token punctuation">,</span></span>
<span class="line">    Risk <span class="token operator">=</span> <span class="token string">"low"</span><span class="token punctuation">,</span></span>
<span class="line">    DisplayName <span class="token operator">=</span> <span class="token string">"获取玩家信息"</span><span class="token punctuation">,</span></span>
<span class="line">    Description <span class="token operator">=</span> <span class="token string">"根据玩家ID获取玩家详细信息"</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token keyword">async</span> <span class="token punctuation">(</span>context<span class="token punctuation">,</span> payload<span class="token punctuation">,</span> ct<span class="token punctuation">)</span> <span class="token operator">=></span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// 解析输入</span></span>
<span class="line">    <span class="token class-name"><span class="token keyword">var</span></span> request <span class="token operator">=</span> JsonSerializer<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">Deserialize</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>PlayerRequest<span class="token punctuation">></span></span></span><span class="token punctuation">(</span>payload<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 业务逻辑</span></span>
<span class="line">    <span class="token class-name"><span class="token keyword">var</span></span> player <span class="token operator">=</span> <span class="token keyword">await</span> _playerService<span class="token punctuation">.</span><span class="token function">GetAsync</span><span class="token punctuation">(</span>request<span class="token punctuation">.</span>PlayerId<span class="token punctuation">,</span> ct<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 返回结果</span></span>
<span class="line">    <span class="token keyword">return</span> JsonSerializer<span class="token punctuation">.</span><span class="token function">Serialize</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token constructor-invocation class-name">PlayerResponse</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        Status <span class="token operator">=</span> <span class="token string">"success"</span><span class="token punctuation">,</span></span>
<span class="line">        Player <span class="token operator">=</span> player</span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 注册函数（简单形式）</span></span>
<span class="line">client<span class="token punctuation">.</span><span class="token function">RegisterFunction</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token constructor-invocation class-name">FunctionDescriptor</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    Id <span class="token operator">=</span> <span class="token string">"item.give"</span><span class="token punctuation">,</span></span>
<span class="line">    Version <span class="token operator">=</span> <span class="token string">"1.0.0"</span><span class="token punctuation">,</span></span>
<span class="line">    Category <span class="token operator">=</span> <span class="token string">"inventory"</span><span class="token punctuation">,</span></span>
<span class="line">    Risk <span class="token operator">=</span> <span class="token string">"medium"</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token keyword">async</span> <span class="token punctuation">(</span>context<span class="token punctuation">,</span> payload<span class="token punctuation">,</span> ct<span class="token punctuation">)</span> <span class="token operator">=></span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// 处理逻辑...</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token keyword">await</span> _inventoryService<span class="token punctuation">.</span><span class="token function">GiveItemAsync</span><span class="token punctuation">(</span>payload<span class="token punctuation">,</span> ct<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 连接并启动服务</span></span>
<span class="line"><span class="token keyword">await</span> client<span class="token punctuation">.</span><span class="token function">ConnectAsync</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">await</span> client<span class="token punctuation">.</span><span class="token function">ServeAsync</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 等待退出信号</span></span>
<span class="line">Console<span class="token punctuation">.</span><span class="token function">WriteLine</span><span class="token punctuation">(</span><span class="token string">"Press Ctrl+C to exit"</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token class-name"><span class="token keyword">var</span></span> tcs <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token constructor-invocation class-name">TaskCompletionSource</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">Console<span class="token punctuation">.</span>CancelKeyPress <span class="token operator">+=</span> <span class="token punctuation">(</span>_<span class="token punctuation">,</span> _<span class="token punctuation">)</span> <span class="token operator">=></span> tcs<span class="token punctuation">.</span><span class="token function">SetResult</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">await</span> tcs<span class="token punctuation">.</span>Task<span class="token punctuation">;</span></span>
<span class="line"></span></code></pre>
